      actions: [incVar("killCount"), setVar("objective", "Return to the fisher."), emit("quest:advanced", (ctx) => ({ questId: FISHER_CRAB_CLEANUP_QUEST_ID, playerId: ctx.bind.player, objective: "Return to the fisher." }))],
      to: "report",
    }] } },
    report: { on: { "dialog:reported": [{
