// ecs/core.js
// Step-based, phase-agnostic ECS core. No timers. No built-in phases. No rendering.
/**
 * @module ecs/core
 * Core ECS primitives: components, entity world, queries, and scheduling hooks.
 *
 * Design goals:
 * - Deterministic and framework-agnostic
 * - Minimal, explicit APIs (no implicit phases)
 * - Efficient queries with cache invalidation upon structural changes
 * - Two store modes: Map-of-records (default) and SoA (struct-of-arrays)
 */

import { composeScheduler, registerSystem } from './systems.js';
import { defineExtension, installWorldExtensionAPI, isExtensionLike } from './extensions.js';
import {
  applyResourceSnapshot,
  installWorldResourceAPI,
  resourceRegistryFromWorld
} from './resources.js';
import { installScriptsAPI, PHASE_SCRIPTS } from './scripts.js';
import { mulberry32 } from './rng.js';

export { defineExtension } from './extensions.js';
export { defineWorldResource } from './resources.js';

const globalConsole = (typeof console !== 'undefined') ? console : null;
const logError = (globalConsole && typeof globalConsole.error === 'function') ? globalConsole.error.bind(globalConsole) : () => {};

/**
 * Base class for concrete runtime events.
 *
 * Events are synchronous, runtime-only messages between producers and consumers.
 * They are not components and are not included in world snapshots.
 */
export class EcsEvent {
  constructor() {
    if (new.target === EcsEvent) {
      throw new Error('EcsEvent is abstract');
    }
  }

  /**
   * Human-readable event name for debugging/logging.
   * Routing uses constructor identity, not this string.
   */
  static get eventName() {
    return this.name;
  }
}

function isEventClass(value) {
  return typeof value === 'function' && (
    value === EcsEvent ||
    value.prototype instanceof EcsEvent
  );
}

